fn solve(x: i8) -> u8 {
    // We'll try all quarter‐turn counts r = 0,1,2,3,
    // compute the resulting orientation A = (-x + 90*r) mod 360 in [0,360),
    // then its deviation dev = min(A, 360−A).
    // We pick the r that minimizes dev, breaking ties by choosing the smaller r.

    let mut best_r: u8 = 0;
    // best_dev initialized to something larger than the maximum possible deviation (180)
    let mut best_dev: i16 = 181;

    for r in 0..4 {
        // Compute raw angle as signed, then reduce modulo 360 into [0,360)
        let raw = -(x as i16) + 90 * (r as i16);
        let a = raw.rem_euclid(360);       // now in [0, 360)
        let dev = if a <= 180 { a } else { 360 - a };

        // Update if we found a strictly smaller deviation.
        // We do not update on equality so that the smaller r wins ties.
        if dev < best_dev {
            best_dev = dev;
            best_r = r as u8;
        }
    }

    best_r
}

